import numpy as np

def transformed(shape):
    mats=[]
    for k in range(4):
        r=np.rot90(shape,k)
        mats.append(r)
        mats.append(np.fliplr(r))
    unique=[]
    for x in mats:
        if not any(x.shape==y.shape and np.array_equal(x,y) for y in unique): unique.append(x)
    return unique

def detect_apply(grid, color):
    arr=np.array(grid); rr,cc=np.where(arr==color)
    r0,r1=rr.min(),rr.max(); c0,c1=cc.min(),cc.max()
    shape=(arr[r0:r1+1,c0:c1+1]==color)
    out=arr.copy()
    for sh in transformed(shape):
        h,w=sh.shape
        for i in range(arr.shape[0]-h+1):
            for j in range(arr.shape[1]-w+1):
                patch=arr[i:i+h,j:j+w]
                if np.all(patch[sh]==0): out[i:i+h,j:j+w][sh]=color
    return out.tolist()

